// Builds src/seed/foods-usda.ts from USDA FoodData Central (public domain data).
// Only foods the FAO West African table (scripts/import-wafct.mjs) doesn't cover.
//
//   npm run foods:import
//
// Reads FDC_API_KEY from .env.local (see .env.example); falls back to the shared, often
// rate-limited DEMO_KEY. Review the printed matches before committing the generated file.

import { writeFileSync } from 'node:fs';

const KEY = process.env.FDC_API_KEY || 'DEMO_KEY';
console.log(KEY === 'DEMO_KEY' ? 'Using shared DEMO_KEY (no FDC_API_KEY in .env.local).' : 'Using your FDC_API_KEY from .env.local.');
const API = 'https://api.nal.usda.gov/fdc/v1';

// name: what you'll search for in the app. fdcId: exact record, or query: search SR Legacy and take the top match.
const FOODS = [
  { name: 'Groundnuts, dry-roasted', fdcId: 173806 },
  { name: 'Powdered milk, whole', query: 'milk dry whole without added vitamin d' },
  { name: 'Evaporated milk', query: 'milk canned evaporated without added vitamin a' },
  { name: 'Spaghetti, cooked', query: 'spaghetti cooked enriched without added salt' },
  { name: 'Banana', query: 'bananas raw' },
];

async function get(url, init) {
  const res = await fetch(url, init);
  if (res.status === 429) throw new Error('USDA rate limit reached. Wait an hour or set FDC_API_KEY to your own free key.');
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  return res.json();
}

for (const f of FOODS.filter((f) => !f.fdcId)) {
  const r = await get(`${API}/foods/search?api_key=${KEY}&dataType=SR%20Legacy&pageSize=1&query=${encodeURIComponent(f.query)}`);
  if (!r.foods?.[0]) throw new Error(`No match for "${f.query}"`);
  f.fdcId = r.foods[0].fdcId;
}

const records = await get(`${API}/foods?api_key=${KEY}`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ fdcIds: FOODS.map((f) => f.fdcId), format: 'full' }),
});
const byId = new Map(records.map((r) => [r.fdcId, r]));
// Nutrient numbers: 208 energy (kcal), 203 protein, 205 carbohydrate, 204 fat.
const amount = (r, num) => r.foodNutrients.find((n) => n.nutrient?.number === num)?.amount ?? 0;

const out = FOODS.map((f) => {
  const r = byId.get(f.fdcId);
  if (!r) throw new Error(`Missing record ${f.fdcId}`);
  console.log(`${f.name.padEnd(40)} ← ${r.fdcId} ${r.description}`);
  return {
    id: `fdc-${r.fdcId}`,
    name: f.name,
    kcal: amount(r, '208'),
    proteinG: amount(r, '203'),
    carbsG: amount(r, '205'),
    fatG: amount(r, '204'),
    measures: (r.foodPortions ?? [])
      .filter((p) => p.gramWeight > 0)
      .slice(0, 4)
      .map((p) => ({
        label: [p.amount, p.modifier || p.measureUnit?.name].filter((x) => x && x !== 'undetermined').join(' '),
        grams: p.gramWeight,
        basis: 'USDA portion weight',
      })),
    source: {
      kind: 'reference',
      citation: `USDA FoodData Central, ${r.dataType}, FDC ID ${r.fdcId}: "${r.description}"`,
      url: `https://fdc.nal.usda.gov/food-details/${r.fdcId}/nutrients`,
    },
    builtIn: true,
  };
});

const file = `// GENERATED by scripts/import-usda.mjs on ${new Date().toISOString().slice(0, 10)}. Do not edit by hand.
// Values are per 100 g, from USDA FoodData Central (public domain).
import type { Food } from '../db';

export const USDA_FOODS: Food[] = ${JSON.stringify(out, null, 2)};
`;
writeFileSync(new URL('../src/seed/foods-usda.ts', import.meta.url), file);
console.log(`\nWrote ${out.length} foods to src/seed/foods-usda.ts`);
